// DB HELPERS
// ═══════════════════════════════════════════════════════════════════════════════
async function dbGetClients() {
  const { data, error } = await supabase.from("clients").select("*").order("created_at", { ascending: false });
  if (error) throw error;
  return data.map(c => ({ id: c.id, company: c.company, contact: c.contact, phone: c.phone, email: c.email, notes: c.notes, createdAt: c.created_at?.split("T")[0] }));
}

async function dbGetProjects() {
  const [{ data: projects, error: pe }, { data: deliverables, error: de },
         { data: invoices, error: ie }, { data: payments, error: pye },
         { data: tasks, error: te }] = await Promise.all([
    supabase.from("projects").select("*").order("created_at", { ascending: false }),
    supabase.from("deliverables").select("*"),
    supabase.from("invoices").select("*"),
    supabase.from("payments").select("*").order("created_at", { ascending: true }),
    supabase.from("tasks").select("*").order("position", { ascending: true }),
  ]);
  if (pe) throw pe; if (de) throw de; if (ie) throw ie; if (pye) throw pye;

  return (projects || []).map(p => {
    const inv = (invoices || []).find(i => i.project_id === p.id);
    const invPayments = inv ? (payments || []).filter(pay => pay.invoice_id === inv.id).map(pay => ({ date: pay.date, amount: Number(pay.amount), method: pay.method })) : [];
    const projDeliverables = (deliverables || []).filter(d => d.project_id === p.id).map(d => ({ id: d.id, name: d.name, size: d.size, type: d.type, data: d.data, uploadedAt: d.uploaded_at }));
    const projTasks = (tasks || []).filter(t => t.project_id === p.id).map(t => ({ id: t.id, title: t.title, description: t.description, status: t.status, dueDate: t.due_date, assignee: t.assignee, position: t.position, createdAt: t.created_at }));
    return {
      id: p.id, clientId: p.client_id, title: p.title, description: p.description,
      posts: p.posts, startDate: p.start_date, deadline: p.deadline,
      designer: p.designer, status: p.status, completedAt: p.completed_at,
      isRecurring: p.is_recurring, recurringNote: p.recurring_note,
      deliverables: projDeliverables, tasks: projTasks,
      invoice: inv ? { id: inv.id, type: inv.type, total: Number(inv.total), advance: Number(inv.advance), received: Number(inv.received), invoiceStatus: inv.invoice_status, uploadedFile: inv.uploaded_file, payments: invPayments } : null
    };
  });
}

async function dbGetLogs() {
  const { data, error } = await supabase.from("activity_logs").select("*").order("created_at", { ascending: false }).limit(200);
  if (error) throw error;
  return data || [];
}

async function dbLog(action, entity, entityId, detail, clientId = null) {
  await supabase.from("activity_logs").insert({ action, entity, entity_id: entityId, detail, client_id: clientId });
}

async function dbSaveClient(client) {
  const row = { id: client.id, company: client.company, contact: client.contact, phone: client.phone, email: client.email, notes: client.notes };
  const { error } = await supabase.from("clients").upsert(row);
  if (error) throw error;
}
async function dbDeleteClient(id) { const { error } = await supabase.from("clients").delete().eq("id", id); if (error) throw error; }

async function dbSaveProject(project) {
  const row = { id: project.id, client_id: project.clientId, title: project.title, description: project.description, posts: project.posts, start_date: project.startDate || null, deadline: project.deadline || null, designer: project.designer, status: project.status, completed_at: project.completedAt || null, is_recurring: project.isRecurring || false, recurring_note: project.recurringNote || null };
  const { error } = await supabase.from("projects").upsert(row);
  if (error) throw error;
}
async function dbDeleteProject(id) { const { error } = await supabase.from("projects").delete().eq("id", id); if (error) throw error; }

async function dbSaveTask(task) {
  const row = { id: task.id, project_id: task.projectId, title: task.title, description: task.description || "", status: task.status, due_date: task.dueDate || null, assignee: task.assignee || null, position: task.position || 0 };
  const { error } = await supabase.from("tasks").upsert(row);
  if (error) throw error;
}
async function dbDeleteTask(id) { const { error } = await supabase.from("tasks").delete().eq("id", id); if (error) throw error; }

async function dbSaveDeliverables(projectId, files) {
  await supabase.from("deliverables").delete().eq("project_id", projectId);
  if (files.length === 0) return;
  const rows = files.map(f => ({ project_id: projectId, name: f.name, size: f.size, type: f.type, data: f.data, uploaded_at: f.uploadedAt || new Date().toISOString() }));
  const { error } = await supabase.from("deliverables").insert(rows);
  if (error) throw error;
}

async function dbSaveInvoice(invoice, projectId, clientId) {
  const row = { id: invoice.id, project_id: projectId, client_id: clientId, type: invoice.type, total: invoice.total || 0, advance: invoice.advance || 0, received: invoice.received || 0, invoice_status: invoice.invoiceStatus, uploaded_file: invoice.uploadedFile || null };
  const { error } = await supabase.from("invoices").upsert(row);
  if (error) throw error;
  await supabase.from("payments").delete().eq("invoice_id", invoice.id);
  if (invoice.payments && invoice.payments.length > 0) {
    const { error: pe } = await supabase.from("payments").insert(invoice.payments.map(p => ({ invoice_id: invoice.id, date: p.date, amount: p.amount, method: p.method })));
    if (pe) throw pe;
  }
}

