function StatusTag({ status, small }) {
  const cfg = STATUS_CFG[status] || STATUS_CFG["Pending"];
  return (
    <span style={{ background: cfg.bg, color: cfg.text, border: `1px solid ${cfg.border}`, padding: small ? "2px 8px" : "4px 11px", borderRadius: 20, fontSize: small ? 10 : 11, fontWeight: 700, display: "inline-flex", alignItems: "center", gap: 5, whiteSpace: "nowrap" }}>
      <span style={{ width: small ? 5 : 6, height: small ? 5 : 6, borderRadius: "50%", background: cfg.dot, display: "inline-block", flexShrink: 0 }} />{status}
    </span>
  );
}

function Spinner({ size = 36 }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: 60, flexDirection: "column", gap: 16 }}>
      <div style={{ width: size, height: size, border: `3px solid ${C.blue}22`, borderTop: `3px solid ${C.blue}`, borderRadius: "50%", animation: "bbspin 0.8s linear infinite" }} />
      <div style={{ color: C.muted, fontSize: 14 }}>Loading...</div>
      <style>{`@keyframes bbspin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

function Toast({ msg, type, onDone }) {
  useEffect(() => { const t = setTimeout(onDone, 3200); return () => clearTimeout(t); }, []);
  const bg = type === "error" ? C.red : "#16A34A";
  const icon = type === "error" ? "✕" : "✓";
  return (
    <div style={{ position: "fixed", bottom: 28, right: 28, background: bg, color: "#fff", borderRadius: 12, padding: "14px 22px", fontSize: 14, fontWeight: 700, zIndex: 9999, boxShadow: "0 8px 30px rgba(0,0,0,0.18)", display: "flex", alignItems: "center", gap: 10, maxWidth: 380 }}>
      <span style={{ background: "rgba(255,255,255,0.25)", borderRadius: "50%", width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12 }}>{icon}</span>
      {msg}
    </div>
  );
}

function Modal({ title, onClose, children, wide, subtitle }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(15,23,42,0.65)", zIndex: 1000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16, backdropFilter: "blur(4px)" }}>
      <div style={{ background: "#fff", borderRadius: 18, width: "100%", maxWidth: wide ? 760 : 600, maxHeight: "93vh", overflow: "auto", boxShadow: "0 32px 80px rgba(0,0,0,0.22)" }}>
        <div style={{ padding: "24px 28px 0", borderBottom: `1px solid ${C.border}`, paddingBottom: 18 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <div>
              <h3 style={{ margin: 0, fontSize: 18, fontWeight: 800, color: C.text }}>{title}</h3>
              {subtitle && <p style={{ margin: "3px 0 0", fontSize: 12, color: C.muted }}>{subtitle}</p>}
            </div>
            <button onClick={onClose} style={{ background: C.subtle, border: `1px solid ${C.border}`, borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16, color: C.muted, display: "flex", alignItems: "center", justifyContent: "center" }}>✕</button>
          </div>
        </div>
        <div style={{ padding: "20px 28px 28px" }}>{children}</div>
      </div>
    </div>
  );
}

function Field({ label, children, required }) {
  return (
    <div style={{ marginBottom: 15 }}>
      <label style={{ display: "block", fontSize: 12, fontWeight: 700, color: C.muted, marginBottom: 6, textTransform: "uppercase", letterSpacing: "0.5px" }}>
        {label}{required && <span style={{ color: C.red, marginLeft: 3 }}>*</span>}
      </label>
      {children}
    </div>
  );
}

function Btn({ onClick, children, variant = "primary", small, disabled, icon }) {
  const styles = {
    primary:   { background: C.gradBtn,       color: "#fff", border: "none" },
    orange:    { background: C.gradOrange,     color: "#fff", border: "none" },
    success:   { background: "linear-gradient(135deg,#16A34A,#22C55E)", color: "#fff", border: "none" },
    danger:    { background: "#FEE2E2",        color: C.red,  border: `1px solid #FECACA` },
    ghost:     { background: "transparent",    color: C.muted,border: `1.5px solid ${C.border}` },
    secondary: { background: C.subtle,         color: C.text, border: `1.5px solid ${C.border}` },
  };
  const s = styles[variant] || styles.primary;
  return (
    <button onClick={onClick} disabled={disabled} style={{ ...s, borderRadius: 9, padding: small ? "5px 12px" : "9px 18px", fontWeight: 700, cursor: disabled ? "not-allowed" : "pointer", fontSize: small ? 12 : 13, whiteSpace: "nowrap", fontFamily: "inherit", display: "inline-flex", alignItems: "center", gap: 6, opacity: disabled ? 0.6 : 1, transition: "opacity 0.15s" }}>
      {icon && <span style={{ fontSize: small ? 12 : 14 }}>{icon}</span>}{children}
    </button>
  );
}

function Card({ children, style }) {
  return <div style={{ background: C.card, borderRadius: 14, boxShadow: "0 1px 4px rgba(0,0,0,0.06), 0 4px 16px rgba(0,0,0,0.04)", border: `1px solid ${C.border}`, ...style }}>{children}</div>;
}

function StatCard({ label, value, icon, color, sub }) {
  return (
    <Card style={{ padding: "18px 20px", display: "flex", alignItems: "center", gap: 14, borderTop: `4px solid ${color}` }}>
      <div style={{ width: 46, height: 46, borderRadius: 12, background: `${color}18`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, flexShrink: 0 }}>{icon}</div>
      <div>
        <div style={{ fontSize: 22, fontWeight: 900, color: C.text, lineHeight: 1.2 }}>{value}</div>
        <div style={{ fontSize: 12, color: C.muted, fontWeight: 600, marginTop: 2 }}>{label}</div>
        {sub && <div style={{ fontSize: 11, color: C.muted, marginTop: 1, opacity: 0.7 }}>{sub}</div>}
      </div>
    </Card>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// TASK MODAL — Add / Edit a subtask
// ═══════════════════════════════════════════════════════════════════════════════
function TaskModal({ data, projectTitle, onSave, onClose, saving }) {
  const [f, setF] = useState({ title: "", description: "", status: "To Do", dueDate: "", assignee: "", ...data });
  const upd = k => e => setF(p => ({ ...p, [k]: e.target.value }));
  return (
    <Modal title={f.id ? "Edit Task" : "New Sub-Task"} subtitle={`Project: ${projectTitle}`} onClose={onClose}>
      <Field label="Task Title" required><input style={inp} value={f.title} onChange={upd("title")} placeholder="e.g. Design Post #1 — Sehri Theme" /></Field>
      <Field label="Description"><textarea style={{ ...inp, height: 64, resize: "vertical" }} value={f.description} onChange={upd("description")} placeholder="Details about this task..." /></Field>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0 14px" }}>
        <Field label="Status"><select style={selS} value={f.status} onChange={upd("status")}>{TASK_STATUSES.map(s => <option key={s}>{s}</option>)}</select></Field>
        <Field label="Due Date"><input style={inp} type="date" value={f.dueDate} onChange={upd("dueDate")} /></Field>
        <Field label="Assignee"><input style={inp} value={f.assignee} onChange={upd("assignee")} placeholder="Designer name" /></Field>
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 8 }}>
        <Btn variant="ghost" onClick={onClose} disabled={saving}>Cancel</Btn>
        <Btn onClick={() => { if (!f.title) { alert("Task title required"); return; } onSave(f); }} disabled={saving}>{saving ? "Saving..." : (f.id ? "Update Task" : "Add Task")}</Btn>
      </div>
    </Modal>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// TASKS PANEL — shown inside project row (expandable)
// ═══════════════════════════════════════════════════════════════════════════════
function TasksPanel({ project, onSaveTask, onDeleteTask, onUpdateTaskStatus, saving }) {
  const [addingTask, setAddingTask] = useState(false);
  const [editTask, setEditTask] = useState(null);
  const tasks = project.tasks || [];

  const taskCols = TASK_STATUSES.map(s => ({ status: s, items: tasks.filter(t => t.status === s) }));
  const done = tasks.filter(t => t.status === "Done").length;
  const pct  = tasks.length > 0 ? Math.round((done / tasks.length) * 100) : 0;

  return (
    <div style={{ background: "#F8FAFF", border: `1px solid ${C.border}`, borderRadius: 12, padding: "16px 18px", margin: "8px 0 4px" }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 14, fontWeight: 800, color: C.text }}>Sub-Tasks</span>
          <span style={{ background: C.blue + "18", color: C.blue, borderRadius: 20, padding: "2px 10px", fontSize: 11, fontWeight: 700 }}>{tasks.length} tasks</span>
          {tasks.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <div style={{ width: 80, height: 6, background: C.border, borderRadius: 10, overflow: "hidden" }}>
                <div style={{ width: `${pct}%`, height: "100%", background: pct === 100 ? "#22C55E" : C.blue, borderRadius: 10, transition: "width 0.3s" }} />
              </div>
              <span style={{ fontSize: 11, color: C.muted, fontWeight: 700 }}>{pct}%</span>
            </div>
          )}
        </div>
        <Btn small onClick={() => setAddingTask(true)} icon="+" disabled={saving}>Add Task</Btn>
      </div>

      {tasks.length === 0 && (
        <div style={{ textAlign: "center", padding: "20px 0", color: C.muted, fontSize: 13 }}>
          No sub-tasks yet. Break this project into smaller tasks for better tracking.
        </div>
      )}

      {/* Kanban-style columns */}
      {tasks.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 10 }}>
          {taskCols.map(col => (
            <div key={col.status}>
              <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", marginBottom: 8, letterSpacing: "0.5px" }}>
                {col.status} <span style={{ color: STATUS_CFG[col.status]?.dot }}>{col.items.length > 0 ? `(${col.items.length})` : ""}</span>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {col.items.map(task => (
                  <div key={task.id} style={{ background: "#fff", border: `1.5px solid ${C.border}`, borderRadius: 10, padding: "10px 12px", cursor: "default" }}>
                    <div style={{ fontWeight: 700, fontSize: 12, color: C.text, marginBottom: 4, lineHeight: 1.3 }}>{task.title}</div>
                    {task.description && <div style={{ fontSize: 11, color: C.muted, marginBottom: 6, lineHeight: 1.4 }}>{task.description}</div>}
                    <div style={{ display: "flex", gap: 4, flexWrap: "wrap", alignItems: "center", marginBottom: 4 }}>
                      {task.dueDate && <span style={{ fontSize: 10, color: C.muted }}>📅 {fmt(task.dueDate)}</span>}
                      {task.assignee && <span style={{ fontSize: 10, color: C.muted }}>👤 {task.assignee}</span>}
                    </div>
                    <div style={{ display: "flex", gap: 4, marginTop: 4 }}>
                      {TASK_STATUSES.filter(s => s !== task.status).slice(0, 1).map(ns => (
                        <button key={ns} onClick={() => onUpdateTaskStatus(task.id, ns)} style={{ background: STATUS_CFG[ns]?.bg, color: STATUS_CFG[ns]?.text, border: `1px solid ${STATUS_CFG[ns]?.border}`, borderRadius: 6, padding: "2px 7px", cursor: "pointer", fontSize: 10, fontWeight: 700, fontFamily: "inherit" }}>→ {ns}</button>
                      ))}
                      <button onClick={() => setEditTask(task)} style={{ background: C.subtle, color: C.muted, border: `1px solid ${C.border}`, borderRadius: 6, padding: "2px 7px", cursor: "pointer", fontSize: 10, fontFamily: "inherit" }}>Edit</button>
                      <button onClick={() => onDeleteTask(task.id)} style={{ background: "#FEE2E2", color: C.red, border: "1px solid #FECACA", borderRadius: 6, padding: "2px 7px", cursor: "pointer", fontSize: 10, fontFamily: "inherit" }}>✕</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {addingTask && <TaskModal data={{}} projectTitle={project.title} onSave={(f) => { onSaveTask({ ...f, id: uid("TSK"), projectId: project.id, position: tasks.length }); setAddingTask(false); }} onClose={() => setAddingTask(false)} saving={saving} />}
      {editTask && <TaskModal data={editTask} projectTitle={project.title} onSave={(f) => { onSaveTask({ ...f, projectId: project.id }); setEditTask(null); }} onClose={() => setEditTask(null)} saving={saving} />}
    </div>
  );
}

