function ClientModal({ data, onSave, onClose, saving }) {
  const [f, setF] = useState({ company: "", contact: "", phone: "", email: "", notes: "", ...data });
  const upd = k => e => setF(p => ({ ...p, [k]: e.target.value }));
  return (
    <Modal title={f.id ? "Edit Client" : "Add New Client"} onClose={onClose}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 14px" }}>
        <Field label="Company Name" required><input style={inp} value={f.company} onChange={upd("company")} placeholder="e.g. ZestBrands" /></Field>
        <Field label="Contact Person"><input style={inp} value={f.contact} onChange={upd("contact")} placeholder="Full name" /></Field>
        <Field label="Phone"><input style={inp} value={f.phone} onChange={upd("phone")} placeholder="0300-1234567" /></Field>
        <Field label="Email"><input style={inp} value={f.email} onChange={upd("email")} placeholder="email@company.pk" /></Field>
      </div>
      <Field label="Notes"><textarea style={{ ...inp, height: 70, resize: "vertical" }} value={f.notes} onChange={upd("notes")} placeholder="Additional notes about this client..." /></Field>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 8 }}>
        <Btn variant="ghost" onClick={onClose} disabled={saving}>Cancel</Btn>
        <Btn onClick={() => { if (!f.company) { alert("Company name required"); return; } onSave(f); }} disabled={saving}>{saving ? "Saving..." : "Save Client"}</Btn>
      </div>
    </Modal>
  );
}

